fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Handle empty matrix case (though problem says non-empty)
    if arr.is_empty() || arr[0].is_empty() {
        return Vec::new();
    }
    
    let rows = arr.len();
    let cols = arr[0].len();
    
    // Create a new matrix with swapped dimensions
    let mut result = vec![vec![0; rows]; cols];
    
    // Fill the transposed matrix
    for i in 0..rows {
        for j in 0..cols {
            result[j][i] = arr[i][j];
        }
    }
    
    result
}